.osr-v2 .osr-mv.trial.oglab-trial-c6, .osr-v2 .osr-mv.refuted.oglab-trial-c6, .osr-v2 .osr-mv.confirmed.oglab-trial-c6, .osr-v2 .osr-mv.merged.oglab-trial-c6 { border-left-color: #8A3D6B; }
