/* Orbace Sudoku Web v4 — design system per PRD Brand Design System.
   Palette/type tokens below follow docs/plans/orbace-phase1-style-recommendations.md:
   --rice/--ivory act as the doc's --paper/--card, --mid/--light collapse onto
   one --ink-soft-equivalent gray (the doc's "kill mixed grays" rule — nothing
   lighter than that on this background reads at AA contrast), and --tea is
   the primary-action color for buttons/links/nav. --verm/--dverm are retired;
   --seal is vermilion (#C41E3A, matches apps/web's seal color) and is the
   color for every seal-chip icon (logo mark, profile/document icons, feature
   and score-card seals) — never buttons, links or errors. */
:root{
  --rice:#F6F1E7; --ivory:#FCFAF4; --ink:#2B2723; --mid:#6B635A; --light:#6B635A;
  --tea:#3E6B4F; --tea-deep:#2C523B; --seal:#C41E3A; --celadon:#B5C9BC; --celadon-d:#8AA894;
  --green:#5B8C5A; --amber:#C9862B; --amber-deep:#96591A; --err:#C4533A; --jade:#0F6B5F;
  /* --fill-green: the color for a PLAYER-entered digit (.og-cell.user), kept apart
     from --tea (buttons/nav/links) so this one change can't ripple into UI chrome.
     UAT feedback (2026-09-24): --tea read as nearly indistinguishable from --ink at
     a glance (worse on su-pu-capture.html's own darker --ink/--tea page override,
     #1C231E vs #244C3A). This is a genuinely brighter, more saturated green
     (~4.4:1 contrast on white, clears AA for the bold/large digit glyphs) so a
     filled cell reads as visibly different from a given the instant you look at
     the board, not just on close inspection. */
  --fill-green:#128A3E;
  /* --amber is for tints/borders/large bold accents; the doc's own --amber-on-paper
     pairing only measures 2.7:1 (fails AA even at the 3:1 large-text floor) — use
     --amber-deep for any amber TEXT on a light surface (mistake digits, inline copy). */
  --serif:'Noto Serif SC','Songti SC','SimSun',serif; --cjk:'Noto Serif SC','Songti SC','SimSun',serif;
  --mono:'IBM Plex Mono',ui-monospace,monospace; --sans:'IBM Plex Sans',-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;
  --line:rgba(43,39,35,.14);
  /* Warm parchment band for the home route's nav+hero, and the replay
     theater's board accent — both new in the "1a Red" palette pass. */
  --header:#EAE2CA; --board-line:#3F4F35;
}
*{margin:0;padding:0;box-sizing:border-box}
body{background:var(--rice);color:var(--ink);font-family:var(--sans);font-size:16px;line-height:1.6}
a{color:inherit;text-decoration:none}
button{font-family:var(--sans);cursor:pointer}
:focus-visible{outline:2px solid var(--tea);outline-offset:2px}

/* ---------- Seals ---------- */
.seal{display:inline-flex;align-items:center;justify-content:center;background:var(--seal);color:#fff;
  font-family:var(--cjk);font-weight:700;border-radius:8px;box-shadow:inset 0 0 0 2px rgba(255,255,255,.25), 0 1px 2px rgba(139,26,43,.35);
  user-select:none;flex-shrink:0}
.seal.lg{width:72px;height:72px;font-size:38px;border-radius:12px}
.seal.md{width:48px;height:48px;font-size:26px}
.seal.sm{width:30px;height:30px;font-size:16px;border-radius:6px}
.seal.outline{background:transparent;color:var(--mid);box-shadow:inset 0 0 0 2px var(--mid)}
.seal-label{font-size:13px;color:var(--mid);text-align:center;margin-top:4px;letter-spacing:.03em}

/* ---------- Top nav ----------
   Parchment --header treatment applied on ALL routes (E2E feedback item 15,
   2026-07-13) so the "Orbace Sudoku" wordmark + 数 seal render identically
   everywhere, not just on #home. Centered at max-width:1280 to line up with
   the home hero / #page-home box. */
nav.top{position:sticky;top:0;z-index:50;background:var(--header);border-bottom:1px solid rgba(46,43,31,.12);
  display:flex;align-items:center;gap:14px;padding:10px 28px;max-width:1280px;margin:0 auto}
nav.top .brand{display:flex;align-items:center;gap:10px;margin-right:auto}
nav.top .brand .brand-name{font-family:var(--serif);font-size:19px;font-weight:600;color:var(--ink)}
nav.top .brand .tag{font-family:var(--cjk);font-size:13px;color:var(--light);letter-spacing:.25em}
nav.top .brand .tag .v1-tag-en{font-family:var(--sans);font-size:10px;letter-spacing:.08em;color:var(--light);opacity:.8;font-weight:500;text-transform:uppercase;margin-left:2px}
nav.top a.navlink,nav.top .navlink{font-size:14px;color:var(--mid);padding:7px 12px;border-radius:6px;font-weight:500}
nav.top a.navlink:hover,nav.top .navlink:hover{background:var(--ivory);color:var(--ink)}
nav.top a.navlink.active,nav.top .navlink.active{color:var(--tea);font-weight:600}
nav.top a.navlink .cjk,nav.top .navlink .cjk{font-family:var(--cjk);color:var(--tea);font-weight:700;font-size:1.2em;margin-right:6px}
nav.top .navlink a{color:inherit;text-decoration:none;display:inline-block;width:100%}

@media (min-width:901px){
  nav.top{padding:14px 40px}
}

/* ---------- Pages ---------- */
.page{display:none;max-width:1060px;margin:0 auto;padding:28px 24px 80px}
.page.visible{display:block;animation:fadein .15s ease-out}
/* #page-home (V1 marketing homepage) is wider than the app's inner pages by
   design (matches the design reference's 1280px canvas) — .page's 1060px is
   right for Play/Ranking/Account/Su-Pu's app-like reading-width UI, but was
   never overridden when the homepage was built, silently capping it to 1060px
   on every screen (~55% width on a 1920px monitor — a real, unintended bug,
   not a deliberate narrower layout). .v1-home-hero's negative margins already
   assume they're bleeding out to this wider boundary, not .page's narrower one. */
#page-home{max-width:1280px}
/* .v1-home-hero bleeds out of #page-home's padding (negative margin) then
   re-pads itself to 40px (matching the design) — but every OTHER homepage
   section (Tea Moment, feature cards, score card, CTA band) has no padding
   of its own and just inherits #page-home's plain 24px, producing a real
   16px left-edge misalignment between the hero's content and every section
   below it. Bump #page-home's own horizontal padding to 40px to match (only
   above the 900px breakpoint, where the hero's own padding is 40px — at
   721-900px the hero already drops to 24px, already matching .page's
   unchanged default, so nothing needs to change in that range). The
   matching .v1-home-hero margin override lives further down, next to its
   base rule — same-specificity rules resolve by SOURCE ORDER regardless of
   which is behind a media query, so it must come after that base rule to
   actually win, not up here. */
@media (min-width:901px){
  #page-home{padding-left:40px;padding-right:40px}
}
@keyframes fadein{from{opacity:0}to{opacity:1}}
@media (prefers-reduced-motion: reduce){*{animation:none!important;transition:none!important}}

h2.section{font-family:var(--serif);font-size:16px;font-weight:600;color:var(--mid);
  display:flex;align-items:center;gap:10px;margin:30px 0 14px}
h2.section::after{content:"";flex:1;height:1px;background:var(--line)}
h2.section .cjk{font-family:var(--cjk);color:var(--ink)}

/* Tea Moment header (2026-07-20): the title's trailing rule line (h2.section::after)
   would otherwise render AFTER the new action link (DOM order: title, link,
   ::after) — squeezing the link away from the right edge instead of flush
   against it. Suppress the rule for this specific header and let the link's
   own margin-left:auto do the right-alignment instead. */
.v1-home-section--with-action::after{content:none}
.v1-tea-title-link{margin-left:auto;white-space:nowrap}

.card{background:var(--ivory);border:1px solid var(--line);border-radius:16px;padding:20px;
