.btn.ghost:hover{background:rgba(62,107,79,.08)}
.btn.dark{background:var(--ink);color:#fff}
.btn.dark:hover{background:#000}
.btn.quiet{background:transparent;color:var(--mid);border:1px solid var(--line)}
.btn.quiet:hover{background:var(--ivory)}
.btn.sm{padding:7px 14px;font-size:13px}
.linkbtn{background:none;border:none;color:var(--tea);font-size:13px;font-weight:500;padding:4px 0}
