.mode-tab .cjk{font-family:var(--cjk);margin-right:5px}

/* ---- Puzzle browser (epic B, docs/plans/2026-07-16-play-playground-search-design.md) ---- */
.v1-play-filters { display: flex; flex-direction: column; gap: 10px; margin-bottom: 20px; }
.v1-play-filter-group { display: flex; flex-wrap: wrap; gap: 8px; }
.v1-play-filter-chip { border: 1px solid var(--line); background: var(--ivory); border-radius: 20px; padding: 6px 14px; font-size: 13px; color: var(--mid); cursor: pointer; }
.v1-play-filter-chip.active { background: var(--tea); border-color: var(--tea); color: #fff; font-weight: 500; }
.v1-play-filter-count { opacity: .65; font-size: 11px; margin-left: 3px; }
.v1-play-results { display: flex; flex-direction: column; gap: 8px; margin-bottom: 16px; }
.v1-play-result-row { display: flex; justify-content: space-between; align-items: center; padding: 10px 14px; border: 1px solid var(--line); border-radius: 8px; background: var(--ivory); cursor: pointer; font-size: 13px; }
.v1-play-result-title { color: var(--mid); font-size: 12px; text-align: right; margin-left: 12px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; max-width: 45%; }
.v1-play-pagination { display: flex; gap: 8px; justify-content: center; }

.play-layout{display:flex;gap:26px;align-items:flex-start}
.board-wrap{flex-shrink:0}
/* .board-wrap is now nested one level inside the .osgc-card OrbaceGameCard.wrap()
 * inserts around it (js/orbace-game-card.js) — .osgc-card, not .board-wrap, is
 * the actual flex item of .play-layout now.
 *
 * UX/CX audit 2026-09-05 §2: this was just flex-shrink:0 (no basis/grow), so
 * .osgc-card never claimed real width of its own — and #playCardBody (inside
 * osgc-card's .osgc-body, which is display:flex;flex-direction:column;
 * align-items:center, css/orbace-game-card.css) doesn't stretch to fill it
 * by default, so the whole board chain collapsed through to .og-board-col's
 * min-width:280px floor (orbace-grid.css) regardless of how wide the page
 * was — measured live at 1920px: board 280px (28%) vs sidebar 706px (72%),
 * the inverse of what a puzzle page should prioritize. Golden-ratio split
 * instead, same pattern (flex ratio + max-width + min-width:0) already used
 * for this identical osgc-card-in-a-split-layout shape elsewhere in this
 * file (.v1-home-tea .osgc-card, .v1-learn-practice .osgc-card). */
.play-layout .osgc-card{flex:1.618 1 0%;max-width:640px;min-width:0}
/* Breaks the .osgc-body align-items:center collapse above — without this,
   raising osgc-card's own width above doesn't reach the actual board,
   since #playCardBody (and everything inside it) still shrinks to fit-content. */
#playCardBody{align-self:stretch}
/* #play's board/cell/numpad/toolrow ruleset (formerly here, duplicating
   orbace-grid.css's .og-* classes) was removed in the move-event-fidelity
   project's Phase 4 (2026-09-04) once #play started rendering through
   OrbaceGrid.mountControlled()'s own generated markup instead of a
   hand-rolled DOM — see js/orbace-grid.js and orbace-grid.css for the
   canonical board/keypad/toolrow styles now shared by every Su-Pu surface. */
.sidebar{flex:1;min-width:230px;max-width:420px;display:flex;flex-direction:column;gap:14px}
.pinfo{display:flex;flex-direction:column;gap:6px;font-size:14px}
.pinfo .title{font-family:var(--cjk);font-size:18px;font-weight:700}
/* Shown when a puzzle/record fetch fails on a genuine network problem —
   matches the homepage Tea Moment's retry treatment (.v1-home-tea-error)
   instead of leaving stale/misleading text with no way to recover but a
   full page reload. Standalone (not scoped to .pinfo) so it works inside
   any meta/status text — e.g. the Su-Pu detail page's card meta line. */
.v1-meta-error{color:var(--amber-deep);cursor:pointer;text-decoration:underline;text-underline-offset:3px}
.pinfo .timer{font-family:var(--mono);font-size:26px;margin-top:4px}
.kbd-help{font-size:12px;color:var(--light);line-height:1.8}
.kbd-help b{font-family:var(--mono);background:var(--ivory);border:1px solid var(--line);border-radius:4px;padding:0 5px;color:var(--mid);font-weight:500}
.stamp-overlay{position:fixed;inset:0;background:rgba(241,234,216,.88);display:none;align-items:center;justify-content:center;
  flex-direction:column;gap:18px;z-index:99;text-align:center}
.stamp-overlay.show{display:flex}
.stamp-overlay .bigseal{width:130px;height:130px;font-size:56px;border-radius:16px;animation:stamp .4s cubic-bezier(.2,1.6,.4,1)}
@keyframes stamp{0%{transform:scale(0);opacity:0}70%{transform:scale(1.15)}100%{transform:scale(1);opacity:1}}
.stamp-overlay h3{font-family:var(--serif);font-size:26px}
.stamp-overlay p{color:var(--mid)}
.modal-overlay{position:fixed;inset:0;background:rgba(0,0,0,.45);display:none;align-items:flex-start;justify-content:center;
  z-index:98;padding:20px;overflow-y:auto}
/* ---------- Toast ----------
   Single site-wide toast component (SPA #toast + static Su-Pu pages
   #supuToast). Anchored top-centre, just under the sticky shell header.

   2026-09-05 fix: the Su-Pu static pages used to ship their own inline
   `.toast{position:fixed;bottom:24px;...}` block on top of this rule. Both
   `top` (here) and `bottom` (there) ended up applying to the same fixed,
   auto-height element, so the box stretched the full height of the viewport
   and "Link copied!" wrapped one word per line — the tall vertical bar
   reported on /su-pu/:id. Those inline blocks are gone; this is the only
   place `.toast` may be positioned. Do not re-declare it per page.

   Toggling visibility/opacity (not display) so the entrance can animate;
   the global prefers-reduced-motion rule above neutralises it. */
.toast{position:fixed;top:var(--toast-top,5rem);left:50%;z-index:100;
  box-sizing:border-box;width:max-content;max-width:min(92vw,30rem);
  padding:12px 18px;background:var(--brand-forest-dark,#17362a);color:#fff;
  border:1px solid rgba(255,255,255,.14);border-radius:12px;
  box-shadow:0 12px 32px rgba(23,54,42,.28),0 2px 8px rgba(23,54,42,.18);
  font-size:14px;line-height:1.45;text-align:center;
  opacity:0;visibility:hidden;pointer-events:none;
  transform:translate(-50%,-10px) scale(.97);
  transition:opacity .22s ease,transform .22s cubic-bezier(.2,.9,.3,1),visibility 0s linear .22s}
.toast.show{opacity:1;visibility:visible;pointer-events:auto;
  transform:translate(-50%,0) scale(1);transition-delay:0s}

/* Structured variant: icon + title + optional detail line. Plain-text
   toasts (t.textContent = "...") keep working and stay centred. */
.toast-row{display:flex;align-items:center;gap:11px;text-align:left}
.toast-icon{flex:none;display:grid;place-items:center;width:26px;height:26px;border-radius:50%;
  background:rgba(255,255,255,.15);color:#d8ecdc}
.toast-icon svg{display:block;width:15px;height:15px}
.toast-body{min-width:0}
.toast-title{display:block;font-weight:600;letter-spacing:.01em}
.toast-detail{display:block;margin-top:2px;font-size:12.5px;color:rgba(255,255,255,.68);
  font-family:var(--mono,ui-monospace,SFMono-Regular,Menlo,monospace);
  white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.toast.is-warn{background:var(--state-warning-deep,#96591A)}
.toast.is-warn .toast-icon{background:rgba(255,255,255,.18);color:#ffe7c2}
@media (max-width:480px){
  .toast{max-width:calc(100vw - 24px);padding:11px 14px}
  .toast-detail{font-size:11.5px}
}

/* ---------- Ranking ---------- */
.period-tabs{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:18px}
.lb-table{width:100%;border-collapse:collapse;font-size:14px}
.lb-table td{padding:11px 8px;border-bottom:1px solid var(--line);vertical-align:middle}
