.profile-card .pname{font-family:var(--serif);font-size:19px;font-weight:600;color:var(--ink)}

/* ---------- Su-Pu replay ---------- */
/* Replay board/controls/move-list now use the canonical .og-board and
   .osr-* styling (css/orbace-supu-replay.css) — see
   docs/orbace-brand-standard.md §Su-Pu Replay Anatomy. */

/* ---------- Account ---------- */
.auth-card{max-width:420px;margin:0 auto;text-align:center}
.auth-card .btn{width:100%;margin-bottom:10px}
.auth-card .divider{display:flex;align-items:center;gap:12px;color:var(--light);font-size:12px;margin:14px 0}
.auth-card .divider::before,.auth-card .divider::after{content:"";flex:1;height:1px;background:var(--line)}
.tiers{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:14px;margin-top:24px}
.tier{font-size:13px;color:var(--mid)}
.tier h4{font-family:var(--serif);font-size:15px;color:var(--ink);margin-bottom:6px}
.settings-group{margin-bottom:8px}
.settings-row{display:flex;align-items:center;justify-content:space-between;gap:14px;padding:13px 0;border-bottom:1px solid var(--line);font-size:14px}
.settings-row:last-child{border-bottom:none}
.settings-row .lbl b{display:block}
.settings-row .lbl span{font-size:12px;color:var(--light)}
.radio-group{display:flex;gap:4px}
.radio-group button{border:1px solid var(--line);background:var(--rice);padding:6px 12px;font-size:12px;color:var(--mid)}
.radio-group button:first-child{border-radius:6px 0 0 6px}
.radio-group button:last-child{border-radius:0 6px 6px 0}
.radio-group button.sel{background:var(--tea);border-color:var(--tea);color:#fff}
.danger{color:var(--err)}

/* ---------- Account shell (Phase 4, 2026-07-22) ---------- */
.account-shell{display:flex;gap:24px;margin-top:16px}
.account-nav{width:160px;flex-shrink:0;display:flex;flex-direction:column;gap:2px}
.account-nav a{display:block;padding:10px 14px;border-radius:8px;font-size:14px;color:var(--mid);text-decoration:none;transition:background .15s,color .15s}
.account-nav a:hover{background:var(--ivory);color:var(--ink)}
.account-nav a.sel{background:var(--tea);color:#fff;font-weight:600}
.account-content{flex:1;min-width:0}
.account-tab{display:none}
.account-tab.visible{display:block}
.acct-heading{font-family:var(--serif);font-size:16px;font-weight:600;margin:0 0 12px}
.acct-stats-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(120px,1fr));gap:12px}
.acct-stat,.acct-comp-stat{text-align:center;padding:16px 8px;background:var(--ivory);border-radius:10px}
.acct-stat-val,.acct-comp-stat .acct-stat-val{display:block;font-family:var(--serif);font-size:24px;font-weight:700;color:var(--tea)}
.acct-stat-lbl,.acct-comp-stat .acct-stat-lbl{display:block;font-size:12px;color:var(--mid);margin-top:4px}
.acct-comp-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}
.acct-comp-period{border-bottom:1px solid var(--line);padding:10px 0}
.acct-comp-period:last-child{border-bottom:none}
.acct-comp-period b{display:block;font-size:14px;margin-bottom:2px}
.acct-comp-period span{font-size:13px;color:var(--mid)}
.acct-sub-list{display:flex;flex-direction:column;gap:0}
.acct-sub-row{display:grid;grid-template-columns:100px 70px 70px 60px 90px 50px auto auto;align-items:center;gap:8px;padding:10px 0;border-bottom:1px solid var(--line);font-size:13px}
.acct-sub-row:last-child{border-bottom:none}
.acct-sub-date{color:var(--mid);font-family:var(--mono);font-size:12px}
.acct-sub-type{font-size:12px;color:var(--light);text-transform:capitalize}
.acct-sub-tier{font-size:12px}
.acct-sub-time{font-family:var(--mono);color:var(--mid);text-align:right}
.acct-sub-points{text-align:right;font-weight:600}
.acct-sub-rank{text-align:center;font-weight:600}
.acct-sub-replay{font-size:12px;color:var(--tea);text-decoration:none;white-space:nowrap;background:none;border:none;padding:0;font-family:inherit;cursor:pointer}
.acct-sub-replay:hover{text-decoration:underline}
@media(max-width:700px){
  .account-shell{flex-direction:column;gap:12px}
  .account-nav{width:100%;flex-direction:row;overflow-x:auto;gap:0;padding-bottom:4px}
  .account-nav a{white-space:nowrap;padding:8px 12px;font-size:13px}
  .acct-sub-row{grid-template-columns:80px 55px auto 50px 70px 40px;font-size:12px;gap:4px}
  .acct-sub-tier,.acct-sub-type{display:none}
  .acct-comp-grid{grid-template-columns:1fr}
}

/* ---------- Today dock ---------- */
.dock-head{font-family:var(--serif);font-size:14px;color:var(--mid);margin:6px 0 10px;display:flex;align-items:center;gap:8px}
.dock-head .cjk{font-family:var(--cjk);color:var(--tea);font-weight:700}
.dock{display:grid;grid-template-columns:repeat(auto-fit,minmax(250px,1fr));gap:12px;margin-bottom:10px}
.dock .d{background:var(--ivory);border:1px solid var(--line);border-radius:12px;padding:13px 15px;display:flex;gap:12px;align-items:center}
.dock .d.live{border-color:rgba(62,107,79,.45);box-shadow:0 0 0 1px rgba(62,107,79,.12)}
.dock .d .tx{flex:1;min-width:0}
.dock .d .tx b{font-size:14px;display:flex;gap:8px;align-items:center}
.dock .d .tx span{font-size:12px;color:var(--mid);display:block;margin-top:2px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.dock .live-pill{font-size:10px;background:var(--tea);color:#fff;border-radius:10px;padding:1px 8px;letter-spacing:.06em}
.dock .btn{white-space:nowrap;flex-shrink:0}

/* ---------- V1 Marketing Homepage (Phase 1) ---------- */

/* ---- Store buttons ----
   Xuan-paper design (2026-07-12 refresh, E2E feedback item 1) — a bordered
   pill with a paper-texture background and a vermilion icon+label, replacing
   the old flat SVG image badges. Nav no longer carries its own store link at
   all (item 11: hero + CTA band + footer already repeat this 3x, a 4th in
   nav was pure clutter). */
.v1-store-btn{position:relative;overflow:hidden;display:inline-flex;align-items:center;min-width:190px;min-height:58px;
  padding:9px 16px;box-sizing:border-box;border:1px solid rgba(139,26,43,.20);border-radius:14px;
  color:var(--seal);text-decoration:none;
  background:
    radial-gradient(circle at 20% 25%, rgba(255,255,255,.45), transparent 28%),
    repeating-linear-gradient(8deg, rgba(122,89,53,.035) 0, rgba(122,89,53,.035) 1px, transparent 1px, transparent 5px),
    linear-gradient(180deg, var(--rice), var(--ivory));
  box-shadow:0 4px 12px rgba(80,55,35,.12), inset 0 1px 0 rgba(255,255,255,.65);
  transition:transform .15s ease, box-shadow .15s ease, color .15s ease}
.v1-store-btn:hover{color:#A91831;transform:translateY(-1px);
  box-shadow:0 7px 17px rgba(80,55,35,.17), inset 0 1px 0 rgba(255,255,255,.7)}
.v1-store-btn__icon{width:26px;height:26px;margin-right:11px;flex:0 0 auto;fill:currentColor;position:relative;z-index:1}
.v1-store-btn__text{display:flex;flex-direction:column;line-height:1.05;position:relative;z-index:1}
.v1-store-btn__eyebrow{font-size:10px;letter-spacing:.03em;opacity:.88}
.v1-store-btn__name{margin-top:2px;font-size:18px;font-weight:650;letter-spacing:-.02em}
/* Footer variant — smaller, matches the old 36px-tall image badges' footprint. */
.v1-store-btn.sm{min-width:150px;min-height:44px;padding:6px 12px}
.v1-store-btn.sm .v1-store-btn__icon{width:20px;height:20px;margin-right:8px}
.v1-store-btn.sm .v1-store-btn__eyebrow{font-size:9px}
.v1-store-btn.sm .v1-store-btn__name{font-size:14px}

/* ---- Dark hero section ---- */
.v1-home-hero{background:var(--header);color:var(--ink);padding:40px 40px 44px;margin:-28px -24px 0;
  border-bottom:1px solid var(--line);
  display:flex;gap:40px;align-items:flex-start;flex-wrap:wrap}
/* Matches #page-home's 40px horizontal padding above 900px (see the .page
   rule block) — must come after the base rule above since same-specificity
   rules resolve by source order, not by which is behind a media query. */
@media (min-width:901px){
  .v1-home-hero{margin-left:-40px;margin-right:-40px}
}
/* flex-grow:0 (not flex:1) so the copy column stops eating the theater's
   headroom on wide screens — flex:1 with no cap let it grow until the
   theater was pushed out to exactly 50% across the viewport regardless of
   how wide the window was, instead of sitting right after the copy
   (E2E feedback item 4). Any leftover row width now sits unused to the
   right of the theater instead of being absorbed by the copy column. */
.v1-home-hero-copy{flex:0 1 460px;min-width:300px;max-width:460px}
/* Now shows today's date (item 3) instead of the static "一局一茶 ONE PUZZLE,
   ONE TEA" line, which moved up into the nav brand tag (item 2) — set
   client-side in js/app.js boot(). */
.v1-home-eyebrow{font-size:13px;letter-spacing:.14em;text-transform:uppercase;color:var(--mid);
  font-weight:600;margin-bottom:14px}
.v1-home-headline{font-family:var(--serif);font-size:44px;font-weight:600;line-height:1.12;letter-spacing:-.015em;margin-bottom:18px;text-wrap:balance}
.v1-home-headline em{font-style:normal;color:var(--tea)}
.v1-home-sub{color:var(--mid);font-size:17px;max-width:500px;margin:0 0 26px;line-height:1.55}
.v1-home-sub b{color:var(--ink)}
/* Primary CTA gets its own row; store links sit together in a secondary row
   below it (never sharing a line with the primary button). */
.v1-home-cta-row{display:flex;margin-bottom:12px}
.v1-home-hero-cta{display:inline-flex;align-items:center;justify-content:center;gap:10px;
  background:var(--tea);color:#fff;border:none;border-radius:10px;
  padding:15px 28px;text-decoration:none;font-weight:600;font-size:17px;cursor:pointer}
.v1-home-hero-cta:hover{background:var(--tea-deep)}
.v1-home-cta-row-secondary{display:flex;gap:12px;flex-wrap:wrap;margin-bottom:20px}
.v1-home-hero-trust{list-style:none;display:flex;flex-wrap:wrap;gap:8px 22px;font-size:13px;color:var(--mid)}
.v1-home-hero-trust li::before{content:"";display:inline-block;width:6px;height:6px;border-radius:50%;
  background:var(--amber);margin-right:8px;vertical-align:2px}

/* ---- Replay theater ----
   Board/controls now use the canonical .og-board/.osr-* styling (brand
   consistency, docs/orbace-brand-standard.md §Su-Pu Replay Anatomy) — this
   rule only constrains size to fit the compact theater card, it no longer
   overrides color/border/background. --og-cell must be redeclared here to
   match this board's actual (narrower) width — it otherwise inherits the
   :root default sized for the full min(540px,92vw) board, which would size
   digits for a 60px cell while the real cell here is only ~47px, badly
   overflowing the cell. */
.v1-home-hero-board.og-board{width:420px;--og-cell:calc(min(420px,92vw) / 9);margin:0 auto}
.v1-home-hero-controls{width:420px;margin:0 auto}
/* #heroCardBody (board+controls) is now nested inside the .osgc-card
 * OrbaceGameCard.wrap() inserts — .osgc-card, not #heroCardBody, is the
 * actual flex item of .v1-home-hero now. flex-shrink alone doesn't help here
 * (flex items have an implicit min-width:auto floor at their content's
 * intrinsic size unless min-width is overridden), so without this the card
 * can't shrink below the 420px board's natural width and overflows the
 * viewport on narrow screens — see the equivalent width:100% override in the
 * max-width:900px block below, which is what actually fixes it. */
.v1-home-hero .osgc-card{min-width:0}
/* .osgc-body's generic centering (css/orbace-game-card.css) shrink-wraps its
 * child to fit-content and centers that box — which makes the child's own
 * width indefinite, breaking the width:100% cascade the two rules above (and
 * the max-width:900px override below) depend on to size the compact 420px
 * board down on narrow phones. Force the hero's #heroCardBody back to a
 * plain 100%-wide stretch (restoring the definite-width chain) and let the
 * board/controls' own margin:0 auto above do the centering instead — same
 * end result, doesn't fight the width:100% math. Confirmed via Playwright at
 * 375px: without this, .v1-home-hero-board renders at its intrinsic 420px
 * and overflows the card by ~55px instead of shrinking to fit. */
.v1-home-hero .osgc-body{align-items:stretch}

/* ---- Tea Moment ----
   64-84px section rhythm per the style guide; halved on narrow phones
   (see the max-width:720px block below) so the page doesn't get too tall. */
.v1-home-section{margin:72px 0 20px}
.v1-home-tea{display:flex;gap:26px;align-items:flex-start;flex-wrap:wrap}
/* Board wrap is 60% of the row at desktop so the grid reads as the dominant
   element and the sidebar takes the remaining ~40% (E2E feedback item 13,
   2026-07-13). The max-width:900px block below resets both columns to full
   width for the stacked mobile layout.
   .v1-home-tea-board-wrap is now nested inside the .osgc-card
   OrbaceGameCard.wrap() inserts — .osgc-card, not .v1-home-tea-board-wrap, is
   the flex item of .v1-home-tea, so the 60%/40% split lives on .osgc-card
   below. .v1-home-tea-board-wrap itself must NOT also carry flex-basis/
   max-width here: OrbaceGameCard.wrap() moves it as-is to become a flex item
   of the new .osgc-body (align-items:center) instead, and a stray
   flex:0 0 60%/max-width:60% there shrinks it to 60% of the *card's* content
   box, well under the 540px .og-board's own width — the grid then overflowed
   its shrunk wrapper and rendered visibly off-center (game-card-branding-
   cleanup Task 6 visual pass, 2026-07-15). position:relative stays: the
    the score card overlay (position:fixed;inset:0) is rendered on top of
    this element. */
.v1-home-tea-board-wrap{position:relative;min-width:0}
.v1-home-tea .osgc-card{flex:0 0 60%;max-width:60%;min-width:0}
/* #v1TeaBoard is just a mount point for the canonical .og-board (js/orbace-grid.js)
 * now — its own size/border/background/paused/font-size rules moved to
 * css/orbace-grid.css's .og-board so this element and the reference page's
 * board stay visually identical. It still needs an explicit size itself
 * (matching .og-board's own min(540px,92vw) square) so the loading placeholder
 * below has something to fill before the grid mounts into it. */
#v1TeaBoard{position:relative;width:min(540px,92vw);aspect-ratio:1}
.v1-home-tea-loading{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;
  font-size:14px;font-style:italic;color:var(--mid);font-family:var(--sans);background:rgba(251,248,239,.94);z-index:2;
  text-align:center;padding:20px}
/* Shown when the daily-puzzle fetch fails outright — was previously left as
   an unrecoverable "Loading…" spinner forever with no retry path. */
.v1-home-tea-loading.v1-home-tea-error{font-style:normal;color:var(--amber-deep);cursor:pointer;
  text-decoration:underline;text-underline-offset:3px}
.v1-home-tea-side{flex:1 1 34%;min-width:250px;display:flex;flex-direction:column;gap:14px}
.v1-tea-card{background:var(--ivory);border:1px solid var(--line);border-radius:16px;padding:20px}
/* Timer panel gets the tea-illustration treatment (mockup: img/tea-moment-bg.jpg
   faded left-to-right so the label/timer text on the left stays legible). */
.v1-tea-card-photo{position:relative;overflow:hidden;background:url("../img/tea-moment-bg.jpg") center/cover no-repeat}
.v1-tea-card-photo::before{content:"";position:absolute;inset:0;
  background:linear-gradient(90deg,rgba(241,234,216,.92) 0%,rgba(241,234,216,.75) 55%,rgba(241,234,216,.15) 100%)}
.v1-tea-card-photo>*{position:relative}
.v1-tea-card-title{font-family:var(--cjk);font-size:23px;font-weight:700}
.v1-tea-card-title span{font-family:var(--sans);font-size:15px;color:var(--mid);font-weight:500}
.v1-tea-timer-row{display:flex;align-items:center;gap:10px;margin-top:6px}
.v1-tea-timer{font-family:var(--mono);font-size:26px}
.v1-tea-timer.paused{opacity:.5}
.v1-tea-pause-btn{background:rgba(251,248,239,.8);border:1px solid var(--line);border-radius:50%;
  width:30px;height:30px;display:flex;align-items:center;justify-content:center;color:var(--ink);cursor:pointer;flex-shrink:0}
.v1-tea-pause-btn:hover{background:var(--ivory)}
.v1-tea-pause-btn .v1-tea-play-icon{display:none}
.v1-tea-pause-btn.on .v1-tea-pause-icon{display:none}
.v1-tea-pause-btn.on .v1-tea-play-icon{display:block}
.v1-tea-timer-hint{font-size:13px;color:var(--mid);margin-top:4px}

/* Number pad + tools (#v1TeaNumpad, #v1TeaTools) are canonical .og-keypad/
 * .og-toolrow mount points now (js/orbace-grid.js) — styling lives in
 * css/orbace-grid.css. */
.v1-tea-help{font-size:13px;color:var(--mid);line-height:1.8}
.v1-tea-help b{font-family:var(--mono);background:var(--ivory);border:1px solid var(--line);border-radius:4px;
  padding:0 5px;color:var(--mid);font-weight:500}
.v1-amber{color:var(--amber-deep)}
.v1-tea-prev{flex:1 1 100%;width:100%;max-width:100%;padding:16px 18px}
.v1-tea-prev-head{font-family:var(--serif);font-size:14px;font-weight:600;margin-bottom:6px;display:flex;align-items:center;gap:8px}
.v1-tea-prev-head .cjk{font-family:var(--cjk);color:var(--tea);font-weight:700;font-size:1.2em}
.v1-tea-prev-list{}
.v1-tea-prev-row{display:flex;align-items:baseline;gap:10px;padding:9px 0;border-top:1px solid var(--line);font-size:13px}
.v1-tea-prev-row:first-child{border-top:none}
.v1-tp-date{color:var(--ink);font-weight:500;white-space:nowrap}
.v1-tp-info{color:var(--mid);flex:1;min-width:0}
.v1-tp-btn{background:none;border:none;color:var(--tea-deep);font-size:13px;font-weight:500;cursor:pointer;padding:0;white-space:nowrap}
.v1-tp-btn:hover{color:var(--tea)}
.v1-tea-prev-link{display:block;font-size:13px;color:var(--tea-deep);font-weight:500;margin-top:10px;padding-top:10px;border-top:1px solid var(--line)}
.v1-tea-prev-link:hover{color:var(--tea)}
/* Inline "Tea Moments" link inside the Home Tea Moment section title (E2E
   feedback 2026-07-13, item 3) — routes to #teamoment. */
.v1-tea-title-link{color:var(--tea);text-decoration:underline;text-underline-offset:3px;text-decoration-thickness:1px}
.v1-tea-title-link:hover{color:var(--tea-deep)}
/* #teamoment history: player's own result per row (E2E item 22, 2026-07-13). */
.v1-tp-result{font-family:var(--mono);font-size:12px;color:var(--tea-deep);white-space:nowrap;margin-left:auto;padding-left:10px}
.v1-tp-result.v1-tp-unsolved{color:var(--light);font-style:italic;font-family:var(--sans)}
.v1-tea-prev-row .v1-tp-btn{margin-left:12px}
/* Item 26 (2026-07-13): per-puzzle catalog stats — completed count + record time. */
.v1-tp-stats{font-size:12px;color:var(--mid);white-space:nowrap;text-align:right;min-width:100px}

/* Su-Pu library list (E2E item 23, 2026-07-13). */
.v1-supu-lib-intro{color:var(--mid);font-size:14px;margin:-8px 0 16px;max-width:640px}
.v1-supu-lib-controls{display:flex;align-items:center;gap:16px;flex-wrap:wrap;margin-bottom:16px}
.v1-supu-lib-tiers{margin:0}
.v1-supu-clean-toggle{font-size:13px;color:var(--mid);display:inline-flex;align-items:center;gap:6px;cursor:pointer;user-select:none}
.v1-supu-lib-list{display:flex;flex-direction:column;gap:0}
.v1-supu-lib-row{display:flex;align-items:baseline;gap:12px;padding:12px 4px;border-top:1px solid var(--line);font-size:14px;flex-wrap:wrap}
.v1-supu-lib-row:first-child{border-top:none}
.v1-sl-tier{font-family:var(--serif);font-weight:600;white-space:nowrap;min-width:96px}
.v1-sl-player{color:var(--ink);white-space:nowrap}
.v1-sl-stats{color:var(--mid);font-size:13px;flex:1;min-width:160px}
.v1-sl-date{color:var(--light);font-size:12px;white-space:nowrap}
.v1-sl-replay{margin-left:auto}
.v1-supu-lib-empty{color:var(--light);font-size:14px;padding:24px 4px;text-align:center}
.v1-supu-lib-empty.v1-meta-error{color:var(--amber-deep);cursor:pointer;text-decoration:underline;text-underline-offset:3px}

/* Su-Pu library inline replay board (E2E feedback item 24, 2026-07-13).
   Board/controls/move-list use the canonical .og-board/.osr-* styling
   (css/orbace-supu-replay.css) — this rule only sizes the wrapper. */
.v1-supu-lib-board-wrap{width:100%;max-width:860px;margin-bottom:20px}
/* Active row highlight — mirrors the pattern of the current row in the
   replay move list. */
.v1-supu-lib-row.v1-sl-active{background:var(--ivory)}

/* ---- Ad slot ----
   Visual design matches the static editorial pages' .static-ad-slot
   (css/static-ads.css) exactly — light tea surface + outlined CTAs,
   centered label — so the homepage ad doesn't look like a different
   product from /learn-sudoku's. Class names stay v1-home-ad-* (unchanged)
   since js/app.js's initAdSlot() selects by them. */
/* Wrapper spans the same content width as the sections around it (top AND
   bottom breathing room, not just top -- 2026-08-10 PM feedback: the real
   AdSense <ins> must stay at its fixed 728x90 declared footprint (Google
   requirement, non-auto format) so that one is explicitly centered with its
   own margin, but the house-ad fallback is just decorative HTML with no
   such constraint -- it expands to the wrapper's full width instead of
   also being pinned to 728px, matching .static-ad-slot's own behavior on
   /learn-sudoku (which has no fixed-width house ad either). */
.v1-home-ad-wrapper{padding:36px 0;max-width:72rem;margin:0 auto}
.v1-home-ad-label{font-size:.68rem;font-weight:700;letter-spacing:.12em;color:var(--text-secondary);text-transform:uppercase;text-align:center;margin-bottom:.5rem}
.v1-home-ad-placeholder{min-height:90px;border:1px dashed var(--line-forest);border-radius:.5rem;
  display:flex;align-items:center;justify-content:center;
  font-size:.85rem;color:var(--text-secondary)}
/* Fixed 728x90 footprint (see index.html comment) — display:none until
   initAdSlot() (js/app.js) activates it post ADS.ENABLED check. Centered
   within the now section-width wrapper. */
.v1-home-ad-ins{display:none;width:728px;max-width:100%;height:90px;margin:0 auto}
/* House ad — shown instead when Google's slot resolves unfilled (see
   initAdSlot()'s data-ad-status watcher). Expands to the full wrapper
   width (no fixed 728px) so it reads as a section, not a stranded banner. */
.v1-home-ad-house{display:none;align-items:center;justify-content:center;gap:.9rem;flex-wrap:wrap;
  width:100%;min-height:90px;
  background:var(--surface-tea);border:1px solid var(--line-forest);border-radius:.5rem;
  padding:1rem;color:var(--text-secondary);box-sizing:border-box;text-align:center}
.v1-home-ad-house-brand{font-family:var(--font-cjk);font-weight:700;font-size:15px;white-space:nowrap;color:var(--brand-forest-dark)}
.v1-home-ad-house-tag{font-size:.85rem;color:var(--text-secondary);flex:1;min-width:0}
.v1-home-ad-house-cta{padding:.45rem .8rem;border:1px solid var(--brand-forest);border-radius:.35rem;
  color:var(--brand-forest);font-size:.85rem;font-weight:700;white-space:nowrap;text-decoration:none;background:transparent}
.v1-home-ad-house-cta:hover{color:#fff;background:var(--brand-forest)}
@media (max-width:600px){
  .v1-home-ad-house{padding:.75rem 1rem}
  .v1-home-ad-house-tag{flex:0 0 100%}
}

/* ---- Feature cards ---- */
.v1-home-features{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:14px}
.v1-home-feat-card{background:var(--ivory);border:1px solid var(--line);border-radius:16px;padding:20px 18px}
.v1-home-feat-seal{display:inline-flex;align-items:center;justify-content:center;width:34px;height:34px;
  background:var(--seal);color:#fff;font-family:var(--cjk);font-weight:700;font-size:18px;border-radius:7px;
  box-shadow:inset 0 0 0 2px rgba(255,255,255,.25)}
.v1-home-feat-title{font-family:var(--serif);font-size:16px;font-weight:600;margin:12px 0 4px}
.v1-home-feat-desc{font-size:13px;color:var(--mid);margin-bottom:10px}
.v1-home-feat-tags{display:flex;flex-wrap:wrap;gap:5px;font-size:13px;color:var(--mid)}
.v1-home-feat-tags span{background:var(--rice);border:1px solid var(--line);border-radius:10px;padding:2px 8px;white-space:nowrap}

/* ---- Learn page: practice pack grid + blog teaser (Task 11; blog list
   itself moved to standalone #blog, blog redesign 2026-07-18 — see
   .v1-blog-* below) ---- */
.v1-learn-pack-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(180px,1fr));gap:12px;margin-bottom:20px}
.v1-learn-pack-card{display:block;padding:16px;border:1px solid var(--line);border-radius:10px;background:var(--ivory);text-decoration:none;color:inherit}
.v1-learn-pack-title{font-weight:600;font-size:14px}
/* Compact "From the Blog" teaser (2-3 rows, small thumbnail + title) —
   deliberately smaller/plainer than the full .v1-blog-card grid, since
   this is a secondary mention pointing at #blog, not the blog's own home. */
.v1-learn-blog-teaser{display:flex;flex-direction:column;gap:8px;margin-bottom:8px}
.v1-learn-blog-teaser-row{display:flex;align-items:center;gap:12px;padding:8px 10px;border:1px solid var(--line);border-radius:8px;text-decoration:none;color:inherit}
.v1-learn-blog-teaser-img{width:56px;height:40px;object-fit:cover;border-radius:6px;flex-shrink:0;background:var(--ivory)}
.v1-learn-blog-teaser-title{font-size:14px}
.v1-learn-qa-placeholder{font-size:13px;color:var(--mid)}

/* ---- Standalone #blog section (blog redesign, 2026-07-18 —
   docs/plans/2026-07-18-blog-redesign-design.md §6). Card grid reuses the
   same visual language as .v1-learn-pack-card/.v1-home-feat-card
   (bordered ivory card, 16px radius) rather than inventing a new pattern. */
.v1-blog-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:16px;margin-bottom:20px}
.v1-blog-card{display:block;border:1px solid var(--line);border-radius:16px;background:var(--ivory);text-decoration:none;color:inherit;overflow:hidden}
.v1-blog-card-img{display:block;width:100%;aspect-ratio:16/9;object-fit:cover;background:var(--rice)}
.v1-blog-card-body{padding:14px 16px}
.v1-blog-card-title{font-family:var(--serif);font-weight:600;font-size:16px;margin-bottom:4px}
.v1-blog-card-excerpt{font-size:13px;color:var(--mid);line-height:1.5;margin-bottom:6px;
  display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}
.v1-blog-card-date{font-size:12px;color:var(--light)}
/* Detail page (#blog/<slug>) */
.v1-blog-hero{display:block;width:100%;max-width:640px;aspect-ratio:16/9;object-fit:cover;border-radius:16px;margin-bottom:16px;background:var(--rice)}
.v1-blog-post-meta{font-size:12px;color:var(--light);margin:-8px 0 16px}
/* `image` content block (heading/paragraph/puzzle_embed already covered by
   .v1-learn-block-* below — image is new, shares the same reading-width
   container via .v1-learn-post-body). */
.v1-blog-block-image{margin:16px 0}
.v1-blog-block-image img{display:block;width:100%;border-radius:10px}
.v1-blog-block-image figcaption{font-size:12px;color:var(--mid);margin-top:6px}
/* `supu_replay` content block (2026-07-18 follow-up) — a full interactive
   replay embed. Deliberately a plain bordered block, not an .osgc-card
   (no brand seal/header) — reads as part of the article, not a separate
   app surface. Reuses .osr-* styling (css/orbace-supu-replay.css)
   unmodified for the board/controls/movelist/explain caption inside. */
.v1-blog-block-replay{margin:16px 0;padding:16px;border:1px solid var(--line);border-radius:12px;background:var(--ivory)}

/* ---- Learn page: practice pack detail view (Task 12) ---- */
.v1-learn-puzzle-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(120px,1fr));gap:8px}
.v1-learn-puzzle-tile{padding:10px;border:1px solid var(--line);border-radius:8px;background:var(--ivory);cursor:pointer;font-size:13px}

/* ---- Learn page: practice grid, side-by-side board+keypad (validation
   feedback, 2026-07-18) — mirrors .v1-home-tea's flex-row split so the
   practice drill reads as the same component family as Tea Moment/#play
   instead of a bare stacked column. OrbaceGameCard.wrap() (js/app.js's
   loadPracticePuzzle()) wraps only #learnPracticeCardBody (the board), so
   .osgc-card — not #learnPracticeCardBody itself — is the flex item of
   .v1-learn-practice, same reasoning as .v1-home-tea's own comment above. */
.v1-learn-practice{display:flex;gap:26px;align-items:flex-start;flex-wrap:wrap}
.v1-learn-practice .osgc-card{flex:0 0 60%;max-width:60%;min-width:0}
.v1-learn-practice-side{flex:1 1 34%;min-width:250px;display:flex;flex-direction:column;gap:14px}
/* Title card at the top of the side column — same .v1-tea-card visual
   language as Tea Moment's own timer card (validation feedback round 2,
   2026-07-18: "a title box similar to tea moment"). .v1-tea-card-title is
   reused as-is for the technique name; only the description line below it
   is new here. */
.v1-learn-practice-title-desc{font-size:13px;color:var(--mid);line-height:1.6;margin-top:6px}
/* Caption explaining why the Show tool highlighted these cells — lives in
   the side column, directly below the keypad (round 2 of validation
   feedback, 2026-07-18; previously under the board). .v1-learn-practice-side
   is a flex column with its own `gap`, so no extra top margin is needed
   here. Hidden via the [hidden] attribute (js/app.js's
   renderTechniqueExplanation()) until Show finds something. */
.v1-learn-practice-explain{padding:12px 14px;border:1px solid var(--line);border-radius:10px;
  background:var(--ivory);font-size:13px;color:var(--mid);line-height:1.6}

/* ---- Learn page: blog post detail view + block rendering (Task 13) ----
   Grid "breakout" pattern (2026-07-18 follow-up: "use the same su-pu
   pattern — move the row-by-row stepping section to the right side of the
   grid"): normal blocks (heading/paragraph/image/puzzle_embed) sit in the
   middle 640px reading-width track for comfortable line length; the
   supu_replay block alone spans the full width of this grid so its
   .osr-layout (css/orbace-supu-replay.css) has enough room to lay the
   move list out beside the board — same side-by-side arrangement the real
   #supu detail page uses — instead of being squeezed into 640px and
   stacking underneath. Every block is a direct child here (renderBlockHtml()
   results are concatenated flat into this container), so this needs no
   wrapper elements, just grid-column placement per child. */
.v1-learn-post-body{display:grid;grid-template-columns:1fr min(640px,100%) 1fr}
.v1-learn-post-body>*{grid-column:2}
.v1-learn-post-body>.v1-blog-block-replay{grid-column:1/4;justify-self:center;width:100%;max-width:900px}
.v1-learn-block-heading{margin:20px 0 8px;font-size:16px}
.v1-learn-block-paragraph{margin:0 0 14px;line-height:1.6;font-size:14px}
.v1-learn-block-embed{margin:16px 0}
.v1-learn-block-caption{font-size:12px;color:var(--mid);margin-bottom:6px}

/* ---- Score card ---- */
.v1-home-score-wrap{display:flex;gap:40px;align-items:center;flex-wrap:wrap}
.v1-home-score-card{width:350px;background:#FBF8EF;border:1px solid var(--line);border-radius:16px;padding:22px;
  box-shadow:0 10px 26px rgba(63,79,53,.08);flex-shrink:0}
.v1-home-score-head{display:flex;gap:12px;align-items:center;margin-bottom:12px}
.v1-home-score-head b{font-size:15px}
.v1-home-score-seal{display:inline-flex;align-items:center;justify-content:center;width:44px;height:44px;
  background:var(--seal);color:#fff;font-family:var(--cjk);font-weight:700;font-size:17px;border-radius:9px;
  box-shadow:inset 0 0 0 2px rgba(255,255,255,.25);flex-shrink:0}
.v1-home-score-sub{font-size:13px;color:var(--mid)}
.v1-home-score-big{text-align:center;font-family:var(--serif);font-size:52px;font-weight:600;margin:2px 0 10px}
.v1-home-score-tags{display:flex;gap:6px;justify-content:center;flex-wrap:wrap;margin-bottom:14px;font-size:13px}
.v1-tag{border-radius:6px;padding:2px 9px}
.v1-tag.practice{border:1px solid #9DB8D2;background:rgba(157,184,210,.15)}
.v1-tag.clean{border:1px solid #8AA894;background:rgba(138,168,148,.15)}
.v1-tag.tier{border:1px solid #D2A49D;background:rgba(210,164,157,.15)}
.v1-home-score-stats{display:grid;grid-template-columns:repeat(4,1fr);gap:6px;text-align:center;
  border-top:1px solid var(--line);border-bottom:1px solid var(--line);padding:10px 0;margin-bottom:12px}
.v1-ss-label{font-size:13px;color:var(--mid)}
.v1-ss-val{font-family:var(--mono);font-size:14px;font-weight:500}
.v1-home-score-breakdown{font-size:13px;color:var(--mid);display:flex;flex-direction:column;gap:4px}
.v1-home-score-breakdown div{display:flex;justify-content:space-between}
.v1-home-score-copy{flex:1;min-width:300px}
.v1-home-score-heading{font-family:var(--serif);font-size:22px;font-weight:600;margin-bottom:12px}
.v1-home-score-points{display:flex;flex-direction:column;gap:12px;font-size:14.5px;color:var(--mid);max-width:420px}
.v1-home-score-point{display:flex;gap:10px}
.v1-home-score-bullet{display:inline-flex;align-items:center;justify-content:center;width:26px;height:26px;
  background:var(--seal);color:#fff;font-family:var(--cjk);font-weight:700;font-size:13px;border-radius:6px;flex-shrink:0}

/* ---- CTA band ----
   Tea-illustration background (img/tea-moment-bg.jpg, from the "1a Red" design
   pass) with a translucent rice-colored wash so cream text stays readable
   over it at any crop. */
.v1-home-cta{margin:36px 0 0;position:relative;border-radius:16px;overflow:hidden;border:1px solid var(--line);
  background:url("../img/cta-bg.jpg") center/cover no-repeat;
  padding:40px 28px;text-align:center;color:var(--ink)}
.v1-home-cta::before{content:"";position:absolute;inset:0;background:rgba(241,234,216,.62)}
.v1-home-cta>*{position:relative}
.v1-home-cta-zh{display:inline-block;height:34px;width:auto;margin-bottom:10px}
.v1-home-cta-headline{font-family:var(--serif);font-size:26px;font-weight:600;margin-bottom:6px}
.v1-home-cta-sub{color:var(--mid);font-size:14px;margin:0 0 20px}
.v1-home-cta-btns{display:flex;gap:12px;justify-content:center;flex-wrap:wrap}

/* ---- Responsive: hero + theater ---- */
@media (max-width:900px){
  /* hero bleed still matches .page's 24px side padding at this width */
  .v1-home-hero{padding:20px 24px 36px;gap:28px}
  .v1-home-headline{font-size:clamp(26px,5vw,34px)}
  .v1-home-sub{font-size:15px}
  /* Container-relative, not viewport-relative: the old min(420px,88vw) sized
     against the raw viewport, ignoring .v1-home-hero's own side padding AND
     .osgc-card's card padding stacked on top of it — on real phones
     that nested padding (32px + 48px) ate into the 12vw margin the vw math
     assumed was free, so the card overflowed past the viewport edge. 100%
     of the actual (already-padded) parent box can't overflow it.
     .osgc-card itself also needs the same width:100% now that it (not
     #heroCardBody) is the direct flex item of .v1-home-hero — a flex item's
     implicit min-width:auto floor otherwise keeps it pinned near the 420px
     board's intrinsic width regardless of flex-shrink, overflowing the
     viewport exactly like the .v1-home-theater bug this comment describes. */
  .v1-home-hero .osgc-card{width:100%}
  .v1-home-hero-board.og-board{width:100%;max-width:420px}
  .v1-home-hero-controls{width:100%;max-width:420px}
  .v1-home-tea-side{flex:1 1 100%;width:100%;max-width:100%}
  /* Same fix as the hero card above: .osgc-card, not .v1-home-tea-board-wrap,
     is the actual flex item of .v1-home-tea now — .v1-home-tea-board-wrap
     itself gets no flex-basis/width overrides here, for the same reason the
     desktop rule above doesn't (it's a flex item of .osgc-body now, not of
     .v1-home-tea). */
  .v1-home-tea .osgc-card{flex:1 1 100%;width:100%;max-width:min(540px,92vw);min-width:0}
  /* Same board/side split as Tea Moment above, applied to the practice
     grid (validation feedback, 2026-07-18: "mobile version use vertical
     alignment"). */
  .v1-learn-practice .osgc-card{flex:1 1 100%;width:100%;max-width:min(540px,92vw);min-width:0}
  .v1-learn-practice-side{flex:1 1 100%;width:100%;max-width:100%}
  .v1-home-score-card{width:100%}
  .v1-home-score-wrap{gap:24px}
}
@media (max-width:720px){
  /* .page padding drops to 16px 14px at this width — match the hero bleed to it */
  .v1-home-hero{margin:-16px -14px 0;padding:18px 16px 30px}
  .v1-home-section{margin:48px 0 16px}
  .v1-home-hero-cta{width:100%}
  .v1-home-cta-row-secondary{justify-content:center}
  .v1-home-numpad,.numpad{gap:4px}
  .v1-home-tea-numpad button{padding:13px 0}
}

/* ---------- Mobile layout ---------- */
.tabbar{display:none}
@media (max-width:900px){
  .play-layout,.replay-layout{flex-direction:column}
  /* Once stacked, the golden-ratio width caps added above (§2 fix) would
     otherwise leave both the board and the sidebar narrow and centered
     instead of filling the column — same width:100% reset this codebase
     already applies to every other .osgc-card/.sidebar split at this kind
     of breakpoint (see the hero/tea/learn-practice rules above). */
  .play-layout .osgc-card{width:100%;max-width:min(540px,92vw)}
  .play-layout .sidebar{width:100%;max-width:none}
  nav.top{padding:10px 14px;flex-wrap:wrap}
  nav.top .brand .tag{display:none}
  .hero h2{font-size:30px}
}
@media (max-width:720px){
  nav.top a.navlink,nav.top .navlink{display:none}
  nav.top{padding:8px 14px}
  .page{padding:16px 14px 108px}
  .hero2{padding:22px 0 8px;gap:26px}
  .hero2 .sub{font-size:15px}
  .hero2 .ctas .btn{width:100%}
  .statstrip{border:none;gap:1px;background:var(--line);border-radius:10px;overflow:hidden}
  .stat{min-width:calc(50% - 1px);flex:1 1 40%;background:var(--rice);border:none!important;padding:16px 10px}
  .stat .n{font-size:21px}
  .dock{grid-template-columns:1fr}
  .cta-band{padding:32px 18px}
  .numpad{gap:4px}
  .numpad button{padding:13px 0;font-size:18px}
  .sidebar{width:100%;min-width:0}
  footer{padding-bottom:96px}
  .stamp-overlay{padding:20px}
  .tabbar{display:flex;position:fixed;bottom:0;left:0;right:0;z-index:60;background:var(--ivory);
    border-top:1px solid var(--line);justify-content:space-around;padding:7px 2px calc(7px + env(safe-area-inset-bottom))}
  /* 7 items as of Ranking Games (2026-07-18, added "Ranking Games") — was 6
     as of the blog redesign (added "Blog"), min-width tightened from 52px to
     44px then so 6 fit on a standard 390px-wide phone without overflowing;
     7×44px + padding still comfortably fits down to 375px. font-size trimmed
     to match. */
  .tabbar a{display:flex;flex-direction:column;align-items:center;gap:3px;font-size:11px;color:var(--mid);padding:2px 3px;min-width:44px;font-weight:500}
  .tabbar a .ts{width:32px;height:32px;border-radius:7px;display:flex;align-items:center;justify-content:center;
    font-family:var(--cjk);font-weight:700;font-size:16px;color:var(--mid);box-shadow:inset 0 0 0 1.5px var(--light)}
  .tabbar a.active{color:var(--tea)}
  .tabbar a.active .ts{background:var(--tea);color:#fff;box-shadow:inset 0 0 0 2px rgba(255,255,255,.25)}
}

/* ============ RANKING GAMES (Phase 4, 2026-07-18) ============
   docs/plans/2026-07-18-web-ranking-games-implementation-plan.md. Reuses
   .card/.btn/.period-tabs/.mode-tab/.lb-table/.badge/.og-* wholesale — only
   the layout shells below are new. Two-column at 901px, matching this
   codebase's existing breakpoint convention (not the 768px the brief/PRD
   assumed — nothing else here uses that value). */
.rgk-stats-bar{display:flex;gap:18px;flex-wrap:wrap;margin-bottom:18px}
.rgk-stat{display:flex;flex-direction:column;gap:2px}
.rgk-stat b{font-family:var(--serif);font-size:20px}
.rgk-stat span{font-size:12px;color:var(--mid)}

.rgk-events{display:grid;grid-template-columns:1fr;gap:14px;margin-bottom:22px}
@media (min-width:901px){.rgk-events{grid-template-columns:repeat(3,1fr)}}
.rgk-event-card{display:flex;flex-direction:column;gap:8px}
.rgk-event-card.rgk-event-empty{opacity:.7}
.rgk-event-label{font-family:var(--serif);font-weight:600;font-size:16px}
.rgk-event-meta{font-size:13px;color:var(--mid)}
.rgk-event-countdown{font-size:12px;color:var(--tea);font-family:var(--mono)}
.rgk-event-card .btn{align-self:flex-start;margin-top:4px}

.rgk-playarea{margin-bottom:22px}
.rgk-play-head{display:flex;align-items:center;justify-content:space-between;margin:12px 0}
.rgk-play-label{font-family:var(--serif);font-weight:600;font-size:16px}
.rgk-timer{font-family:var(--mono);font-size:18px;color:var(--tea)}
.rgk-og-wrap{margin-top:8px}

.rgk-result{text-align:center;padding:24px 12px}
.rgk-result-title{font-family:var(--serif);font-size:18px;font-weight:600;margin-bottom:6px}
.rgk-result-points{font-family:var(--serif);font-size:32px;font-weight:700;color:var(--tea)}
.rgk-result-bonus{font-size:13px;color:var(--amber);margin-top:6px}
.rgk-result-rank{font-size:13px;color:var(--mid);margin-top:4px}
.rgk-result .btn{margin-top:16px}

.rgk-loading,.rgk-signin{padding:24px;text-align:center;color:var(--mid)}
.rgk-signin .btn{margin-top:12px}

/* Leaderboard period title + Prev/Next (2026-07-22) */
.rgk-lb-period-bar{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:10px}
.rgk-lb-period-title{font-family:var(--serif);font-weight:600;font-size:15px;color:var(--ink)}
.rgk-lb-period-bar .btn[disabled]{opacity:.35;pointer-events:none}

/* Inline "View my replay" board (2026-07-22) — reuses .og-board/.osr-controls */
.rgk-replay-inline{margin-top:16px;text-align:left}
.rgk-replay-inline .og-board{max-width:360px;margin:0 auto}

/* V8 Weekly Cup semantic card (Team Web M1, js/app.js's renderWeeklyCupCard,
 * variant data from js/compete-weekly.js). Reuses the site's existing
 * tokens rather than a parallel palette -- --tea for the CTA, --seal never
 * for state, --amber reserved for mistakes only (there are none on this
 * card), matching the signed-off Pass 3 reference's own rule against a
 * fourth visual system and its rule against red/green as generic state
 * color. Provisional vs. final is carried by the quiet .wc-final-mark line
 * and full-weight numerals, not by a color change. */
.wc-card{text-align:left}
.wc-kicker{font-size:11px;font-weight:700;letter-spacing:.12em;text-transform:uppercase;color:var(--mid)}
/* Phase 3 config title (Team Web M2) — "This Week's Official Cup" /
 * "Today's Official Puzzle" / "Monthly Championship" — sits above the
 * per-variant .wc-headline, same serif token, one step larger/bolder to
 * read as the card's own name rather than a state line. */
.wc-title{font-family:var(--serif);font-size:28px;font-weight:700;margin:4px 0 2px}
.wc-headline{font-family:var(--serif);font-size:24px;font-weight:600;margin:6px 0;font-variant-numeric:tabular-nums}
.wc-final-mark{font-size:13px;color:var(--tea);font-weight:600;margin:0 0 8px}
.wc-body{margin:4px 0;color:var(--ink)}
.wc-meta{margin:4px 0;font-size:13px;color:var(--mid)}
